mapper.select:
select count(1) from basket_match m
where m.is_delete = 0 and m.season_id = #{seasonId}
and m.match_status = #{matchStatus}
and m.data_status = #{dataStatus}

select count(1) from basket_match
where is_delete = 0 and season_id = #{seasonId}
  and match_status in (0, 1, 2, 4)

select count(1) from (
    select team_id from basket_match_team_stat
    where is_delete = 0 and match_id = #{matchId}
    group by team_id having count(1) > 1
) t

select count(1) from (
    select player_id from basket_match_player_stat
    where is_delete = 0 and match_id = #{matchId}
    group by player_id having count(1) > 1
) t
